176	+import type { Account } from "./session.ts";
177	+import { bearer as realBearer } from "./session.ts";
178	+import type { Store } from "./store.ts";
179	+import { attachedRun } from "./state.ts";
180	+
181	+export interface WireDeps {
182	+  WebSocket: typeof WebSocket;
183	+  fetch: typeof fetch;
184	+  bearer: (a: Account) => Promise<string | null>;
185	+  now: () => number;
186	+  random: () => number;
187	+}
188	+
189	+export interface Wire {
190	+  connect(): void;
191	+  disconnect(): void;
192	+  press(p: { press: string; move?: string; answer?: Record<string, unknown> }): string | null;
193	+}
194	+
195	+/** The app's own rule: a second, doubling, capped at half a minute, with a little jitter. */
196	+function backoffMs(attempt: number, random: () => number): number {
197	+  return Math.min(30_000, 1000 * 2 ** attempt) * (0.8 + random() * 0.4);
198	+}
199	+
200	+/**
201	+ * One socket to Runlog, as a deck.
202	+ *
203	+ * It attaches signed in and names no run; the server pushes the held
204	+ * list, the store picks, and this watches whichever it picked so the
205	+ * doorbell rings here too. A ring is a fetch of the snapshot on the
206	+ * signed-in route, which is where the offer is. A press names the run
207	+ * and the offer's `seq`, so the page can refuse one the run has moved
208	+ * past.
209	+ */
210	+export function openWire(account: Account, store: Store, deps: WireDeps = realDeps()): Wire {
211	+  let socket: WebSocket | null = null;
212	+  let wanted = false;
213	+  let attempt = 0;
214	+  let watching: string | null = null;
215	+  const wsBase = account.apiBase.replace(/^http/, "ws");
216	+
217	+  const fetchSnapshot = async (run: string) => {
218	+    const token = await deps.bearer(account);
219	+    if (!token) return;
220	+    try {
221	+      const res = await deps.fetch(`${account.apiBase}/api/sessions/${encodeURIComponent(run)}/snapshot`, {
222	+        headers: { authorization: `Bearer ${token}` },
223	+      });
224	+      if (res.ok) store.dispatch({ t: "snapshot", snapshot: (await res.json()) as never });
225	+    } catch {
226	+      /* the next ring tries again */
227	+    }
228	+  };
229	+
230	+  const follow = () => {
231	+    const run = attachedRun(store.state);
232	+    if (run === watching || !socket) return;
233	+    watching = run;
234	+    if (run) {
235	+      socket.send(JSON.stringify({ t: "watch", id: run }));
236	+      void fetchSnapshot(run);
237	+    }
238	+  };
239	+  store.subscribe(follow);
240	+
241	+  const open = async () => {
242	+    if (!wanted) return;
243	+    const token = await deps.bearer(account);
244	+    if (!token) {
245	+      store.dispatch({ t: "session", state: "expired" });
246	+      return;
247	+    }
248	+    store.dispatch({ t: "socket", state: "connecting" });
249	+    const ws = new deps.WebSocket(`${wsBase}/ws?token=${encodeURIComponent(token)}&as=deck`);
250	+    socket = ws;
251	+    ws.onopen = () => {
252	+      attempt = 0;
253	+      watching = null;
254	+      store.dispatch({ t: "socket", state: "open" });
255	+      ws.send(JSON.stringify({ t: "hello" }));
256	+    };
257	+    ws.onmessage = (e) => {
258	+      let m: Record<string, unknown>;
259	+      try {
260	+        m = JSON.parse(String(e.data)) as Record<string, unknown>;
261	+      } catch {
262	+        return;
263	+      }
264	+      if (m["t"] === "runs" && Array.isArray(m["runs"])) store.dispatch({ t: "runs", runs: m["runs"] as never, any: m["any"] === true });
265	+      else if (m["t"] === "changed" && m["id"] === watching && watching) void fetchSnapshot(watching);
266	+      else if (m["t"] === "drove" && typeof m["ref"] === "string")
267	+        store.dispatch({
268	+          t: "drove",
269	+          ref: m["ref"],
270	+          ok: m["ok"] === true,
271	+          ...(typeof m["say"] === "string" ? { say: m["say"] } : {}),
272	+          ...(typeof m["seq"] === "number" ? { seq: m["seq"] } : {}),
273	+        });
274	+    };
275	+    ws.onclose = () => {
276	+      socket = null;
277	+      store.dispatch({ t: "socket", state: "closed" });
278	+      if (wanted) setTimeout(() => void open(), backoffMs(attempt++, deps.random));
279	+    };
280	+  };
281	+
282	+  return {
283	+    connect() {
284	+      wanted = true;
285	+      void open();
286	+    },
287	+    disconnect() {
288	+      wanted = false;
289	+      socket?.close();
290	+    },
291	+    press(p) {
292	+      const run = attachedRun(store.state);
293	+      const seq = store.state.snapshot?.offer?.seq;
294	+      if (!run || seq === undefined || !socket) return null;
295	+      const ref = `sd-${deps.now().toString(36)}-${Math.floor(deps.random() * 1e6).toString(36)}`;
296	+      socket.send(JSON.stringify({ t: "drive", run, seq, ref, ...p }));
297	+      return ref;
298	+    },
299	+  };
300	+}
301	+
302	+function realDeps(): WireDeps {
303	+  return {
304	+    WebSocket: globalThis.WebSocket,
305	+    fetch: (i, o) => fetch(i, o),
306	+    bearer: realBearer,
307	+    now: () => Date.now(),
308	+    random: () => Math.random(),
309	+  };
310	+}
