317	+import { initial, reduce, type DeckEvent, type DeckState } from "./state.ts";
318	+
319	+export interface Store {
320	+  state: DeckState;
321	+  dispatch(e: DeckEvent): void;
322	+  subscribe(l: (s: DeckState) => void): () => void;
323	+}
324	+
325	+/** The one live state, and the actions that redraw when it moves. */
326	+export function makeStore(now: () => number = Date.now): Store {
327	+  const listeners = new Set<(s: DeckState) => void>();
328	+  const store: Store = {
329	+    state: initial(),
330	+    dispatch(e) {
331	+      const next = reduce(store.state, e, now());
332	+      if (next === store.state) return;
333	+      store.state = next;
334	+      for (const l of listeners) l(next);
335	+    },
336	+    subscribe(l) {
337	+      listeners.add(l);
338	+      return () => listeners.delete(l);
339	+    },
340	+  };
341	+  return store;
342	+}

